import { path } from '@servicenow/sdk-build-core'
import { createTestContext, findInput, getMergedRecordUpdates, loadTestFile, unzipInputArray } from './test-utils'
import { getUtcTime } from '../../test-utils'

describe('Action Data Types Test Suite', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    describe('Update Record action with TemplateValueColumn', () => {
        test('Update Record action with TemplateValue maps configuration correctly', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'flow-def-datatypes.now.ts', 'create')

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(1)

            const triggerInstance = merged['sys_hub_trigger_instance_v2'][0]
            const triggerInputsArr = unzipInputArray(triggerInstance.trigger_inputs)
            const triggerInputs = (name: string) => findInput(triggerInputsArr, name)?.value

            const expectedTime = getUtcTime(10, 30, 15)
            expect(triggerInputs('time')).toBe(expectedTime)

            expect(merged['sys_hub_action_instance_v2']).toHaveLength(2)

            const actionInstance1 = merged['sys_hub_action_instance_v2'][0]
            const actionInstance1InputsArr = unzipInputArray(actionInstance1.values)
            const actionInstance1Inputs = (name: string) => findInput(actionInstance1InputsArr, name)?.value

            expect(actionInstance1Inputs('table_name')).toBe('incident')
            expect(actionInstance1Inputs('values')).toBe('category=network^short_description=VPN issue^priority=1^EQ')

            const actionInstance2 = merged['sys_hub_action_instance_v2'][1]
            const actionInstance2InputsArr = unzipInputArray(actionInstance2.values)
            const actionInstance2Inputs = (name: string) => findInput(actionInstance2InputsArr, name)?.value

            expect(actionInstance2Inputs('record')).toContain('.record}}')
            expect(actionInstance2Inputs('watermark_email')).toBe(true)
            expect(actionInstance2Inputs('ah_to')).toContain('.record.assigned_to.email}}')
            expect(actionInstance2Inputs('ah_subject')).toContain('.record.number}}')
            expect(actionInstance2Inputs('ah_body')).toContain('Please look into the incident.')
        })
    })
})

describe('Trigger Data Types Test Suite for transform', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    describe('Created trigger with datapills in CreateRecord action', () => {
        test('TemplateValueColumn with datapills transform check', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('sys_hub_flow_06e072fc379a7a540e11a3e734924ba6.xml', 'datatypes/xmls')
            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_06e072fc379a7a540e11a3e734924ba6.xml',
                content: xmlContent,
            })

            expect(changedFiles).toHaveLength(1)
            expect(changedFiles[0].getName()).toBe('sys_hub_flow_06e072fc379a7a540e11a3e734924ba6.now.ts')

            const content = changedFiles[0].getContent()

            //Verify Created trigger inputs
            expect(content).toContain('wfa.trigger')
            expect(content).toContain('trigger.record.created')
            expect(content).toContain(`table: 'incident'`)

            //Verify Create Record action inputs with datapills
            expect(content).toContain('wfa.action')
            expect(content).toContain('action.core.createRecord')
            expect(content).toContain(`table_name: 'incident_task'`)
            expect(content).toContain(`values: TemplateValue({`)
            expect(content).toContain(
                "short_description: wfa.dataPill(_params.trigger.current.short_description, 'string')"
            )
            expect(content).toContain("assigned_to: wfa.dataPill(_params.trigger.current.assigned_to, 'reference')")
            expect(content).toContain("description: wfa.dataPill(_params.trigger.current.description, 'string')")
            expect(content).toContain(`state: '1'`)
        })
    })

    describe('Monthly trigger with CreateRecord action', () => {
        test('Test for DurationColumn and TemplateValueColumn', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('sys_hub_flow_69412d5837ce72d00e11a3e734924b96.xml', 'datatypes/xmls')
            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_69412d5837ce72d00e11a3e734924b96.xml',
                content: xmlContent,
            })

            expect(changedFiles).toHaveLength(1)
            expect(changedFiles[0].getName()).toBe('sys_hub_flow_69412d5837ce72d00e11a3e734924b96.now.ts')

            const content = changedFiles[0].getContent()

            //Verify monthly trigger inputs
            expect(content).toContain('day_of_month: 10')
            expect(content).toContain('time: Time')
            expect(content).toContain('UTC')
            expect(content).toContain('hours: 15')
            expect(content).toContain('minutes: 30')

            //Verify create record action inputs
            expect(content).toContain(`table_name: 'incident'`)
            expect(content).toContain('values: TemplateValue({')
            expect(content).toContain(`category: 'hardware'`)
            expect(content).toContain(`short_description: 'Network issue'`)
        })
    })
    describe('Repeat trigger transform test for Duration column', () => {
        test('Test for DurationColumn', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('sys_hub_flow_85b1fd5c37cab2d00e11a3e734924b42.xml', 'datatypes/xmls')
            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_85b1fd5c37cab2d00e11a3e734924b42.xml',
                content: xmlContent,
            })

            expect(changedFiles).toHaveLength(1)
            expect(changedFiles[0].getName()).toBe('sys_hub_flow_85b1fd5c37cab2d00e11a3e734924b42.now.ts')

            const content = changedFiles[0].getContent()

            //Verify repeat trigger inputs
            expect(content).toContain('repeat: Duration({')
            expect(content).toContain('days: 15')
            expect(content).toContain('hours: 10')
            expect(content).toContain('minutes: 30')
        })
    })
})

describe('XML to Fluent -> Unsupported datatypes test suite', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    test('Test for Dynamic Inputs column in subflow inputs', async () => {
        const project = ctx.createProject()

        const xmlContent = loadTestFile('sys_hub_flow_9e967c6237d632100e11a3e734924b3b.xml', 'datatypes/xmls')
        const { changedFiles } = await project.transform({
            path: 'sys_hub_flow_9e967c6237d632100e11a3e734924b3b.xml',
            content: xmlContent,
        })

        expect(changedFiles).toHaveLength(3)
        expect(changedFiles[0].getName()).toBe('sys_hub_flow_9e967c6237d632100e11a3e734924b3b.now.ts')

        const content = changedFiles[0].getContent()

        //Verify Record() API got created
        expect(content).toContain('Record')
        expect(content).toContain(`table: 'sys_hub_flow'`)
        expect(content).toContain(`name: 'Subflow for dynamic choices'`)
        expect(content).toContain(`table: 'sys_hub_flow_input'`)
        expect(content).toContain(`element: 'variable'`)
        expect(content).toContain('dynamic=true')
    })
})

describe('Flow Variable Column Test Suite', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    test('Test boolean column inside flow object does not transform additional attributes - DEF0786409', async () => {
        const project = ctx.createProject()

        const xmlContent = loadTestFile('sys_hub_flow_07eeda8f3d12fe10f87795b672f00030.xml', 'datatypes/xmls')
        const { changedFiles } = await project.transform({
            path: 'sys_hub_flow_07eeda8f3d12fe10f87795b672f00030.xml',
            content: xmlContent,
        })

        expect(changedFiles).toHaveLength(1)
        expect(changedFiles[0].getName()).toBe('sys_hub_flow_07eeda8f3d12fe10f87795b672f00030.now.ts')

        const content = changedFiles[0].getContent()
        expect(content).toContain('remote: BooleanColumn')
        expect(content).toContain("label: 'remote'")

        const booleanColumnMatch = content.match(/remote:\s*BooleanColumn\({([^}]+)}\)/s)
        expect(booleanColumnMatch).toBeTruthy()

        if (booleanColumnMatch) {
            const booleanColumnContent = booleanColumnMatch[1]
            const attributeNames =
                booleanColumnContent.match(/(\w+)\s*:/g)?.map((match) => match.replace(':', '').trim()) || []

            const actualAttributeSet = new Set(attributeNames)
            const expectedCoreAttributeSet = new Set(['label', 'default'])

            const invalidAttributes: string[] = []
            for (const actualAttribute of actualAttributeSet) {
                if (!expectedCoreAttributeSet.has(actualAttribute)) {
                    invalidAttributes.push(actualAttribute)
                }
            }

            expect(invalidAttributes).toHaveLength(0)
        }
    })
})
